// 遍历所有已连接账号
// 检测登录状态和Cookie有效性
async function checkAllAccounts() {
  const accounts = []; // 从本地存储读取
  const results = [];
  for (const acc of accounts) {
    const status = { id: acc.id, valid: true, need_relogin: false };
    results.push(status);
  }
  return { account_statuses: JSON.stringify(results), need_relogin_list: JSON.stringify(results.filter(r => r.need_relogin)) };
}
const result = await checkAllAccounts();
return result;

